mapper.update:
update oc_document_version
set process_status = '1',
    process_message = #{processMessage}
where document_version_id = #{documentVersionId}
  and del_flag = '0'

update oc_document_version
set process_status = '3',
    process_message = #{processMessage}
where document_version_id = #{documentVersionId}
  and del_flag = '0'

update oc_document_version
set process_status = '0',
    process_message = #{processMessage}
where document_version_id = #{documentVersionId}
  and del_flag = '0'

update oc_document_version
set index_status = '1',
    index_message = #{indexMessage}
where document_version_id = #{documentVersionId}
  and del_flag = '0'
  and process_status = '2'

update oc_document_version
set index_status = '3',
    index_message = #{indexMessage}
where document_version_id = #{documentVersionId}
  and del_flag = '0'

update oc_document_version set del_flag = '2' where document_id in
#{documentId}
and del_flag = '0'
